"""Generate CHANGELOG.md from commit subjects and gate pull requests on them.

A release note edited by hand drifts from the commits it describes, so derive it and check it.
"""

from __future__ import annotations

import argparse
import re
import subprocess
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
OUTPUT = "CHANGELOG.md"

INTRO = (
    "Generated from commit subjects by `ops/release/changelog.py`; "
    "do not edit this file by hand."
)

TYPES = (
    "feat",
    "fix",
    "perf",
    "refactor",
    "docs",
    "test",
    "build",
    "ci",
    "chore",
    "revert",
)
GROUPS = (
    ("feat", "Features"),
    ("fix", "Fixes"),
    ("perf", "Performance"),
    ("refactor", "Refactoring"),
    ("docs", "Documentation"),
    ("test", "Tests"),
    ("build", "Build"),
    ("ci", "CI"),
    ("chore", "Chores"),
    ("revert", "Reverts"),
    ("milestone", "Milestones"),
)

_CONVENTIONAL = re.compile(
    r"^(?P<type>" + "|".join(TYPES) + r")(?:\([^()]+\))?!?: (?P<subject>\S.*)$"
)
_LEGACY = re.compile(r"^(?:m\d+(?:\.\d+)*|FinScrape-t\d+|FinScrape|plan):\s+\S")


def _git(repo: Path, *args: str) -> str:
    result = subprocess.run(
        ["git", "-C", str(repo), *args],
        capture_output=True,
        check=False,
        text=True,
        encoding="utf-8",
        errors="replace",
    )
    if result.returncode != 0:
        raise SystemExit(result.stderr.strip() or f"git {' '.join(args)} failed")
    return result.stdout


def _classify(subject: str) -> tuple[str | None, str]:
    """Return the group key and the text to print, or (None, subject) when unrecognised."""
    match = _CONVENTIONAL.match(subject)
    if match:
        return match.group("type"), match.group("subject").strip()
    if _LEGACY.match(subject):
        return "milestone", subject
    return None, subject


def _reason(subject: str) -> str:
    return (
        "subject is neither a Conventional Commit "
        f"({'|'.join(TYPES)}) nor a legacy m<version>:, FinScrape-t<n>:, "
        f"FinScrape: or plan: form: {subject!r}"
    )


def lint(subject: str) -> str | None:
    if _classify(subject)[0] is not None:
        return None
    return _reason(subject)


def _tags(repo: Path) -> list[str]:
    tags = [line.strip() for line in _git(repo, "tag", "--list", "v*").splitlines()]
    tags = [tag for tag in tags if tag]
    return sorted(tags, key=_version_key, reverse=True)


def _version_key(tag: str) -> tuple[int, ...]:
    return tuple(int(part) for part in re.findall(r"\d+", tag))


def _tag_date(repo: Path, tag: str) -> str:
    return _git(repo, "log", "-1", "--format=%cs", tag).strip()


def _commits(repo: Path, rev_range: str) -> list[tuple[str, str]]:
    args = ["log", "--format=%h%x09%s"]
    if rev_range:
        args.append(rev_range)
    commits: list[tuple[str, str]] = []
    for line in _git(repo, *args).splitlines():
        sha, _, subject = line.partition("\t")
        subject = subject.strip()
        if sha and subject:
            commits.append((sha, subject))
    return commits


def _render_section(title: str, tag_date: str | None, commits: list[tuple[str, str]]) -> str:
    lines = [f"## {title} - {tag_date}" if tag_date else f"## {title}"]
    grouped: dict[str, list[tuple[str, str]]] = {key: [] for key, _ in GROUPS}
    other = 0
    for sha, subject in commits:
        key, text = _classify(subject)
        if key is None:
            other += 1
        else:
            grouped[key].append((text, sha))

    for key, label in GROUPS:
        entries = grouped[key]
        if not entries:
            continue
        lines.append("")
        lines.append(f"### {label}")
        lines.extend(f"- {text} (`{sha}`)" for text, sha in entries)

    if other:
        lines.append("")
        lines.append("### Other changes")
        lines.append(f"- {other} commit subjects predate the convention; see git log")
    return "\n".join(lines)


def render_version(repo: Path, tag: str) -> str:
    tags = _tags(repo)
    if tag == "Unreleased":
        if not tags:
            return "## Unreleased\n\nNo releases tagged yet."
        return _render_section("Unreleased", None, _commits(repo, f"{tags[0]}..HEAD"))
    if tag not in tags:
        return f"## {tag}"
    position = tags.index(tag)
    older = tags[position + 1] if position + 1 < len(tags) else None
    rev_range = f"{older}..{tag}" if older else tag
    return _render_section(tag, _tag_date(repo, tag), _commits(repo, rev_range))


def render(repo: Path) -> str:
    tags = _tags(repo)
    blocks = ["# Changelog", INTRO]
    if not tags:
        blocks.append("## Unreleased\n\nNo releases tagged yet.")
        return "\n\n".join(blocks) + "\n"

    sections: list[str] = []
    older: str | None = None
    for tag in reversed(tags):
        rev_range = f"{older}..{tag}" if older else tag
        sections.append(_render_section(tag, _tag_date(repo, tag), _commits(repo, rev_range)))
        older = tag
    sections.reverse()

    ahead = _git(repo, "rev-list", "--count", f"{tags[0]}..HEAD").strip()
    if ahead and int(ahead) > 0:
        sections.insert(0, _render_section("Unreleased", None, _commits(repo, f"{tags[0]}..HEAD")))

    blocks.extend(sections)
    return "\n\n".join(blocks) + "\n"


def _write(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8", newline="\n")


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        description="Generate CHANGELOG.md from Conventional Commit subjects."
    )
    action = parser.add_mutually_exclusive_group(required=True)
    action.add_argument("--write", action="store_true", help="regenerate CHANGELOG.md")
    action.add_argument("--check", action="store_true", help="fail if CHANGELOG.md is stale")
    action.add_argument("--lint", metavar="MESSAGE", help="check one commit subject")
    action.add_argument("--check-range", metavar="A..B", help="check subjects in a git range")
    action.add_argument("--version", metavar="TAG", help="render one release section")
    parser.add_argument("--output", type=Path, help="write --version output here instead")
    parser.add_argument("--repo", type=Path, help="repository root (defaults to this tree)")
    args = parser.parse_args(argv)

    repo = args.repo.resolve() if args.repo else ROOT

    if args.write:
        target = repo / OUTPUT
        _write(target, render(repo))
        print(f"wrote {target}")
        return 0

    if args.check:
        target = repo / OUTPUT
        current = target.read_text(encoding="utf-8") if target.exists() else ""
        if current != render(repo):
            print(f"{OUTPUT} is stale; run `python ops/release/changelog.py --write`")
            return 1
        print(f"{OUTPUT} is current")
        return 0

    if args.lint is not None:
        reason = lint(args.lint)
        if reason:
            print(reason)
            return 1
        print("ok")
        return 0

    if args.check_range is not None:
        output = _git(repo, "log", "--format=%s", args.check_range)
        subjects = [line.strip() for line in output.splitlines()]
        offenders = [subject for subject in subjects if subject and lint(subject)]
        if offenders:
            for subject in offenders:
                print(f"offending subject: {subject}")
            return 1
        print(f"{args.check_range}: all subjects follow the convention")
        return 0

    text = render_version(repo, args.version or "")
    if args.output:
        _write(args.output, text + "\n")
    else:
        print(text)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
